et landelijke zuiden en het geïndustrialiseerde noorden van Engeland. Haar ontmoetingen brengen haar in een wereld waarin sociale rechtvaardigheid en economische belangen met elkaar botsen. Tegelijk ontwikkelt zich een liefdesverhaal dat haar eigen opvattingen op de proef stelt. De roman verbindt haar persoonlijke ontwikkeling met vragen over de positie van vrouwen en de verhoudingen tussen mensen uit verschillende maatschappelijke groepen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1473572/noord-en-zuid.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/1473572/noord-en-zuid.html","sha256":"6732f16fdd26d6e1011f5f316eb077b9ce31726cc9dca71ccd9aeb12e733d63c","checkedAt":"2026-11-01T14:02:35.488Z","fact":"Paperback ISBN 9789491618796 verschijningsdatum 17/08/2021 NUR 302 Vertaalde literaire roman, novelle imprint Astoria Uitgeverij uitgever Vrije Uitgevers, De taal Nederlands","sourceAuthors":"Elizabeth Gaskell","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789403885797","key":{"id":977200125},"before":null,"after":{"work_id":977100041,"title":"1984","language":"nld","isbn_13":"9789403885797","isbn_10":null,"open_library_edition_id":null,"publisher":"Mijnbestseller B.V.","id":977200125}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403885797","key":{"edition_id":"@edition:9789403885797"},"before":null,"after":{"edition_id":"@edition:9789403885797","work_id":977100041,"bound_author_id":921301381,"bound_title":"1984","bound_language":"nld","bound_isbn13":"9789403885797","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000762569_1984_0_0.jpg","card_cover_url":null,"evidence_url":